test('diagnostic labels preserve human context without retained physical codes', () => {
  expect(diagnosticDisplayText('pffv5-p5-recipient-1786468614871_10432 — Работник')).toBe('Диагностическая проверка — Работник');
  expect(diagnosticDisplayText('__PFFV4_PFFV4_20260727T075200Z__ Линия')).toBe('Диагностическая проверка Линия');
  expect(diagnosticDisplayText('__PFFV5_P10_123__ и __PFFV5_P12_456__')).toBe('Диагностическая проверка и Диагностическая проверка');
  for (const label of ['Отдел испытаний', 'Проверка упаковки', 'PFFV5 оборудование', 'Демонстрационный стенд']) {
    expect(diagnosticDisplayText(label)).toBe(label);
  }
  expect(diagnosticDisplayText(null, 'Без подразделения')).toBe('Без подразделения');
});

type ScreenId =
  | 'Shift' | 'ShiftHistory' | 'People' | 'Admin' | 'Situation' | 'Tasks' | 'Wash' | 'OKK'
  | 'Stock' | 'Orders' | 'Checklists' | 'Defrost' | 'Returns' | 'Log' | 'Chats'
  | 'Announcements' | 'Archive' | 'Notifications' | 'Ops' | 'Report';

type Finding = {
  viewport: string;
  screen: string;
  kind: string;
  value: string;
};

type SurfaceEvidence = {
  viewport: string;
  screen: string;
  heading: string;
  controls: number;
  textLength: number;
  overflow: number;
  screenshot: string;
};

type InteractionEvidence = {
  viewport: string;
  screen: string;
  control: string;
  result: 'PASS' | 'MISSING' | 'FAIL';
  detail: string;
};

