      const jobCode = jobPanel.getByPlaceholder('электрик', { exact: true });
      await jobName.fill(`Локальная должность ${viewport}`);
      await jobCode.fill(`local-title-${viewport}`);
      const jobSelects = jobPanel.getByRole('combobox');
      const roleSelect = jobSelects.nth(0);
      const roleOptions = await roleSelect.locator('option').evaluateAll((options) => options.map((option) => (option as HTMLOptionElement).value).filter(Boolean));
      if (roleOptions.length > 1) await roleSelect.selectOption(roleOptions.at(-1)!);
      await jobSelects.nth(1).selectOption('24');
      const departmentSelect = jobSelects.nth(2);
      const departmentOptions = await departmentSelect.locator('option').evaluateAll((options) => options.map((option) => (option as HTMLOptionElement).value).filter(Boolean));
      if (departmentOptions.length) await departmentSelect.selectOption(departmentOptions[0]);
