      await jobPanel.getByPlaceholder('Что делает эта должность', { exact: true }).fill('Локальный черновик без сохранения');
      await expect(jobPanel.getByRole('button', { name: 'Создать должность', exact: true })).toBeEnabled();
      const jobObserved = await inspectSurface(page, viewport, 'Админка / черновик должности', 'admin-job-title-create-draft');
      evidence.surfaces.push(jobObserved.surface);
      evidence.findings.push(...jobObserved.findings);
      await jobCode.focus();
      await page.goBack();
      await expect(jobCode).not.toBeFocused();
      await expect(page.getByRole('heading', { name: /Администрирование/ })).toBeVisible();
      await page.goBack();
      await expect(page.getByRole('heading', { name: /^Смена$/ })).toBeVisible();
      await openMain(page, views.find((view) => view.id === 'Admin')!);
      await openAdminSection('Должности и роли');
      await expect(page.locator('.admin-setup-panel').filter({ has: page.getByRole('heading', { name: 'Создать должность', exact: true }) }).getByPlaceholder('Например: Электрик', { exact: true })).toHaveValue('');
      evidence.interactions.push({ viewport, screen: 'Админка / должности', control: 'Поля должности / focus Back / screen Back / reopen clean', result: 'PASS', detail: 'Name/code, server role/department options, 24-hour mode, permission label and description changed only local state; focus Back blurred, second Back left Admin, and reopening restored a clean create form.' });

      await openAdminSection('Отделы и службы');
      const departmentPanel = page.locator('.admin-setup-panel').filter({ hasText: 'Создать отдел или общую службу' }).first();
      await departmentPanel.scrollIntoViewIfNeeded();
