test('admin-external-company-confirm-readonly: disable and restore layers close without mutation', async ({ page }, testInfo) => {
  test.skip(testInfo.project.name !== 'desktop-edge', 'Explicit viewport coverage runs once.');
  test.setTimeout(240_000);
  const evidence = { interactions: [] as InteractionEvidence[], gaps: [] as string[], surfaces: [] as SurfaceEvidence[], findings: [] as Finding[] };
  for (const width of [1440, 360, 390, 430]) {
    const viewport = width === 1440 ? 'desktop' : String(width);
    await page.setViewportSize({ width, height: 844 });
    await loginAsAdmin(page);
    await openMain(page, views.find((view) => view.id === 'Admin')!);
    const writes: string[] = [];
    const guardWrite = async (route: import('@playwright/test').Route) => {
      const request = route.request();
      if (!['GET', 'HEAD', 'OPTIONS'].includes(request.method())) {
        writes.push(`${request.method()} ${new URL(request.url()).pathname}`);
        await route.abort();
        return;
      }
      await route.continue();
    };
    await page.route('**/api/admin/**', guardWrite);
    try {
      await page.locator('.admin-task-nav').getByRole('button', { name: 'Должности и роли', exact: true }).click();
      const companyPanel = page.locator('.admin-setup-panel').filter({ has: page.getByRole('heading', { name: 'Фирмы наёмных работников', exact: true }) });
      await companyPanel.scrollIntoViewIfNeeded();
      const activeRow = companyPanel.locator('article.admin-row').filter({ has: page.getByRole('button', { name: 'Отключить', exact: true }) }).first();
      if (await activeRow.count()) {
        await activeRow.getByRole('button', { name: 'Отключить', exact: true }).click();
        let dialog = page.getByRole('dialog').filter({ has: page.getByRole('heading', { name: /^Отключить фирму / }) });
        await expect(dialog).toBeVisible();
        const reason = dialog.getByLabel('Причина', { exact: true });
        await reason.fill(`Локальная проверка фирмы ${viewport}`);
        await expect(dialog.getByRole('button', { name: 'Подтвердить', exact: true })).toBeEnabled();
        const disableObserved = await inspectSurface(page, viewport, 'Админка / подтверждение отключения фирмы', 'admin-external-company-disable-confirm');
        evidence.surfaces.push(disableObserved.surface);
        evidence.findings.push(...disableObserved.findings);
        await reason.focus();
        await page.goBack();
        await expect(reason).not.toBeFocused();
        await expect(dialog).toBeVisible();
        await page.goBack();
        await expect(dialog).toBeHidden();
        await activeRow.getByRole('button', { name: 'Отключить', exact: true }).click();
        dialog = page.getByRole('dialog').filter({ has: page.getByRole('heading', { name: /^Отключить фирму / }) });
        await dialog.getByRole('button', { name: 'Отмена', exact: true }).click();
        await expect(dialog).toBeHidden();
      } else {
        evidence.gaps.push(`${viewport}: no active external company exists; disable confirmation remains unproved.`);
      }

      const inactiveRow = companyPanel.locator('article.admin-row.dimmed').filter({ has: page.getByRole('button', { name: 'Восстановить', exact: true }) }).first();
      if (await inactiveRow.count()) {
        await inactiveRow.getByRole('button', { name: 'Восстановить', exact: true }).click();
        const dialog = page.getByRole('dialog').filter({ has: page.getByRole('heading', { name: /^Восстановить фирму / }) });
        await expect(dialog).toBeVisible();
        await expect(dialog.getByLabel('Причина', { exact: true })).toHaveCount(0);
        await expect(dialog.getByRole('button', { name: 'Подтвердить', exact: true })).toBeEnabled();
        const restoreObserved = await inspectSurface(page, viewport, 'Админка / подтверждение восстановления фирмы', 'admin-external-company-restore-confirm');
        evidence.surfaces.push(restoreObserved.surface);
        evidence.findings.push(...restoreObserved.findings);
        await page.goBack();
        await expect(dialog).toBeHidden();
      } else {
        evidence.gaps.push(`${viewport}: no inactive external company exists; restore confirmation remains unproved.`);
      }
      if (await activeRow.count() && await inactiveRow.count()) {
        evidence.interactions.push({ viewport, screen: 'Админка / фирмы наёмных работников', control: 'Отключить и восстановить / причина / Back / Отмена', result: 'PASS', detail: 'An active company opened required-reason disable confirmation and an inactive company opened reason-free restore confirmation; focus Back, layer Back and visible Cancel closed without submit.' });
      }
      expect(writes).toEqual([]);
    } finally {
      await page.unroute('**/api/admin/**', guardWrite);
      fs.writeFileSync(path.join(runtimeDir, 'runtime-admin-external-company-confirm-readonly.json'), JSON.stringify(evidence, null, 2) + '\n');
    }
  }
});

