test('admin-work-area-drafts-readonly: area and position fields discard through Back', async ({ page }, testInfo) => {
  test.skip(testInfo.project.name !== 'desktop-edge', 'Explicit viewport coverage runs once.');
  test.setTimeout(240_000);
  const evidence = {
    interactions: [] as InteractionEvidence[],
    gaps: [] as string[],
    surfaces: [] as SurfaceEvidence[],
    findings: [] as Finding[],
    measurements: [] as Array<{ viewport: string; actionBottom: number; navigationTop: number | null; overlapPx: number }>,
  };
  for (const width of [1440, 360, 390, 430]) {
    const viewport = width === 1440 ? 'desktop' : String(width);
    await page.setViewportSize({ width, height: 844 });
    await loginAsAdmin(page);
    await openMain(page, views.find((view) => view.id === 'Admin')!);
    const writes: string[] = [];
    const guardWrite = async (route: import('@playwright/test').Route) => {
      const request = route.request();
      if (!['GET', 'HEAD', 'OPTIONS'].includes(request.method())) {
        writes.push(`${request.method()} ${new URL(request.url()).pathname}`);
        await route.abort();
        return;
      }
      await route.continue();
    };
    await page.route('**/api/admin/**', guardWrite);
    try {
      const sectionButton = page.locator('.admin-task-nav').getByRole('button', { name: 'Повременщики / рабочие зоны', exact: true });
      await sectionButton.click();
      await expect(sectionButton).toHaveClass(/active/);

      const areaPanel = page.locator('.admin-setup-panel').filter({ has: page.getByRole('heading', { name: 'Создать рабочую зону', exact: true }) });
      await areaPanel.scrollIntoViewIfNeeded();
      const areaName = areaPanel.getByPlaceholder('Разбор коробов', { exact: true });
      const areaDescription = areaPanel.getByPlaceholder('Для повременщиков и подсобных работ', { exact: true });
      await areaName.fill(`Локальная зона ${viewport}`);
      const areaSelects = areaPanel.getByRole('combobox');
      const departmentOptions = await areaSelects.nth(0).locator('option').evaluateAll((options) => options.map((option) => (option as HTMLOptionElement).value).filter(Boolean));
      if (departmentOptions.length) await areaSelects.nth(0).selectOption(departmentOptions[0]);
      await areaSelects.nth(1).selectOption('TIME');
      await areaDescription.fill('Локальный черновик повременщиков без сохранения');
      await expect(areaPanel.getByRole('button', { name: 'Создать рабочую зону', exact: true })).toBeEnabled();
      const areaObserved = await inspectSurface(page, viewport, 'Админка / черновик рабочей зоны', 'admin-work-area-create-draft');
      evidence.surfaces.push(areaObserved.surface);
      evidence.findings.push(...areaObserved.findings);
      evidence.interactions.push({ viewport, screen: 'Админка / рабочие зоны', control: 'Поля рабочей зоны / local draft', result: 'PASS', detail: 'Name, a real department when available, TIME assignment kind and description changed only local state; Create became enabled but was not clicked.' });

      const positionPanel = page.locator('.admin-setup-panel').filter({ has: page.getByRole('heading', { name: 'Добавить позицию рабочей зоны', exact: true }) });
      const positionSelect = positionPanel.getByRole('combobox');
      const positionAreaOptions = await positionSelect.locator('option').evaluateAll((options) => options.map((option) => (option as HTMLOptionElement).value).filter(Boolean));
      if (positionAreaOptions.length) {
        await positionSelect.selectOption(positionAreaOptions[0]);
        const title = positionPanel.getByPlaceholder('Грузчик', { exact: true });
        const numberInputs = positionPanel.getByRole('spinbutton');
        await title.fill(`Локальная позиция ${viewport}`);
        await numberInputs.nth(0).fill('2');
        await numberInputs.nth(1).fill('3');
        await numberInputs.nth(2).fill('4');
        const addPosition = positionPanel.getByRole('button', { name: 'Добавить позицию', exact: true });
        await expect(addPosition).toBeEnabled();
        await positionPanel.scrollIntoViewIfNeeded();
        const positionObserved = await inspectSurface(page, viewport, 'Админка / черновик позиции рабочей зоны', 'admin-work-area-position-create-draft');
        evidence.surfaces.push(positionObserved.surface);
        evidence.findings.push(...positionObserved.findings);
        await addPosition.evaluate((element) => element.scrollIntoView({ block: 'center', inline: 'nearest' }));
        const layout = await page.evaluate(() => {
          const action = [...document.querySelectorAll('button')].find((button) => button.textContent?.trim() === 'Добавить позицию');
          const navigation = [...document.querySelectorAll<HTMLElement>('.bottom-nav, .mobile-quick-nav')]
            .find((candidate) => getComputedStyle(candidate).display !== 'none' && candidate.getBoundingClientRect().height > 0) ?? null;
          if (!action) throw new Error('Work-area position action is missing');
          const actionRect = action.getBoundingClientRect();
          const navigationRect = navigation?.getBoundingClientRect() ?? null;
          return {
            actionBottom: actionRect.bottom,
            navigationTop: navigationRect?.top ?? null,
            overlapPx: navigationRect ? Math.max(0, actionRect.bottom - navigationRect.top) : 0,
          };
        });
        evidence.measurements.push({ viewport, ...layout });
        expect(layout.overlapPx, `${viewport}: Add position must scroll above the fixed bottom navigation`).toBe(0);
        const lowerObserved = await inspectSurface(page, viewport, 'Админка / черновик позиции рабочей зоны / нижние действия', 'admin-work-area-position-create-draft-lower');
        evidence.surfaces.push(lowerObserved.surface);
        evidence.findings.push(...lowerObserved.findings);
        evidence.interactions.push({ viewport, screen: 'Админка / рабочие зоны', control: 'Поля позиции / focus Back / screen Back / reopen clean', result: 'PASS', detail: 'A real work area, title and min/plan/max changed only local state; focus Back blurred, screen Back left Admin, and reopening restored both clean forms.' });
        await numberInputs.nth(2).focus();
      } else {
        evidence.gaps.push(`${viewport}: no real work area option; position draft controls remain unproved`);
        await areaDescription.focus();
      }

      await page.goBack();
      await expect(page.locator(':focus')).toHaveCount(0);
      await expect(page.getByRole('heading', { name: /Администрирование/ })).toBeVisible();
      await page.goBack();
      await expect(page.getByRole('heading', { name: /^Смена$/ })).toBeVisible();
      await openMain(page, views.find((view) => view.id === 'Admin')!);
      await page.locator('.admin-task-nav').getByRole('button', { name: 'Повременщики / рабочие зоны', exact: true }).click();
      const reopenedAreaPanel = page.locator('.admin-setup-panel').filter({ has: page.getByRole('heading', { name: 'Создать рабочую зону', exact: true }) });
      const reopenedPositionPanel = page.locator('.admin-setup-panel').filter({ has: page.getByRole('heading', { name: 'Добавить позицию рабочей зоны', exact: true }) });
      await expect(reopenedAreaPanel.getByPlaceholder('Разбор коробов', { exact: true })).toHaveValue('');
      await expect(reopenedAreaPanel.getByRole('combobox').nth(1)).toHaveValue('WORK_AREA');
      await expect(reopenedPositionPanel.getByPlaceholder('Грузчик', { exact: true })).toHaveValue('');
      await expect(reopenedPositionPanel.getByRole('spinbutton').nth(0)).toHaveValue('1');
      expect(writes).toEqual([]);
    } finally {
      await page.unroute('**/api/admin/**', guardWrite);
      fs.writeFileSync(path.join(runtimeDir, 'runtime-admin-work-area-drafts-readonly.json'), JSON.stringify(evidence, null, 2) + '\n');
    }
  }
});

