test('admin-factory-status-confirm-readonly: protected layer closes without mutation', async ({ page }, testInfo) => {
  test.skip(testInfo.project.name !== 'desktop-edge', 'Explicit viewport coverage runs once.');
  test.setTimeout(240_000);
  const evidence = { interactions: [] as InteractionEvidence[], gaps: [] as string[], surfaces: [] as SurfaceEvidence[], findings: [] as Finding[] };
  for (const width of [1440, 360, 390, 430]) {
    const viewport = width === 1440 ? 'desktop' : String(width);
    await page.setViewportSize({ width, height: 844 });
    await loginAsAdmin(page);
    await openMain(page, views.find((view) => view.id === 'Admin')!);
    const writes: string[] = [];
    const guardWrite = async (route: import('@playwright/test').Route) => {
      const request = route.request();
      if (!['GET', 'HEAD', 'OPTIONS'].includes(request.method())) {
        writes.push(`${request.method()} ${new URL(request.url()).pathname}`);
        await route.abort();
        return;
      }
      await route.continue();
    };
    await page.route('**/api/admin/**', guardWrite);
    try {
      await page.locator('.admin-task-nav').getByRole('button', { name: 'Заводы', exact: true }).click();
      const factoryCard = page.locator('.factory-context-card').filter({ has: page.getByRole('button', { name: 'Деактивировать', exact: true }) });
      if (!(await factoryCard.count())) {
        evidence.gaps.push(`${viewport}: current selected factory is not active; protected deactivate confirmation remains unproved.`);
        expect(writes).toEqual([]);
        continue;
      }
      const factoryName = (await factoryCard.getByRole('heading', { name: /^Выбран завод:/ }).innerText()).replace(/^Выбран завод:\s*/, '').trim();
      const deactivate = factoryCard.getByRole('button', { name: 'Деактивировать', exact: true });
      await deactivate.scrollIntoViewIfNeeded();
      await deactivate.click();
      let dialog = page.getByRole('dialog').filter({ has: page.getByRole('heading', { name: `Деактивировать ${factoryName}`, exact: true }) });
      await expect(dialog).toBeVisible();
      const confirmText = dialog.getByLabel('Введите: ЗАВОД', { exact: true });
      const reason = dialog.getByLabel('Причина', { exact: true });
      await confirmText.fill('ЗАВОД');
      await reason.fill(`Локальная проверка завода ${viewport}`);
      await expect(dialog.getByRole('button', { name: 'Подтвердить', exact: true })).toBeEnabled();
      const observed = await inspectSurface(page, viewport, 'Админка / подтверждение деактивации завода', 'admin-factory-disable-confirm');
      evidence.surfaces.push(observed.surface);
      evidence.findings.push(...observed.findings);
      await reason.focus();
      await page.goBack();
      await expect(reason).not.toBeFocused();
      await page.goBack();
      await expect(dialog).toBeHidden();
      await deactivate.click();
      dialog = page.getByRole('dialog').filter({ has: page.getByRole('heading', { name: `Деактивировать ${factoryName}`, exact: true }) });
      await dialog.getByRole('button', { name: 'Отмена', exact: true }).click();
      await expect(dialog).toBeHidden();
      evidence.interactions.push({ viewport, screen: 'Админка / заводы', control: 'Деактивировать / ЗАВОД / причина / focus Back / Отмена', result: 'PASS', detail: `The active selected factory ${factoryName} opened its protected confirmation; exact confirmation text plus reason enabled confirm, while focus/layer Back and separate visible Cancel closed without submit.` });
      expect(writes).toEqual([]);
    } finally {
      await page.unroute('**/api/admin/**', guardWrite);
      fs.writeFileSync(path.join(runtimeDir, 'runtime-admin-factory-status-confirm-readonly.json'), JSON.stringify(evidence, null, 2) + '\n');
    }
  }
});

