      evidence.interactions.push({ viewport, screen: 'Админка / заводы', control: 'Обновить / factory reload', result: 'PASS', detail: 'Refresh reloaded the selected factory through canonical Admin GET requests and received config-health HTTP 200.' });

      const contextList = section.locator('.factory-context-list');
