      const diagnosticsToggle = section.getByRole('button', { name: 'Показать диагностику заводов', exact: true });
      await diagnosticsToggle.click();
      await expect(section.getByRole('button', { name: 'Скрыть диагностику заводов', exact: true })).toBeVisible();
      const expandedObserved = await inspectSurface(page, viewport, 'Админка / заводы / диагностика раскрыта', 'admin-factory-list-diagnostics-expanded');
      evidence.surfaces.push(expandedObserved.surface);
      evidence.findings.push(...expandedObserved.findings);
      evidence.interactions.push({ viewport, screen: 'Админка / заводы', control: 'Показать / Скрыть диагностику заводов', result: 'PASS', detail: 'The diagnostic factory list expanded and later collapsed without changing server state.' });

      const diagnosticChip = section.locator('.admin-factory-strip .factory-chip').first();
