      const positionPanel = page.locator('.admin-setup-panel').filter({ has: page.getByRole('heading', { name: 'Добавить позицию', exact: true }) });
      const selectedPositionLine = positionPanel.getByRole('combobox', { name: 'Линия', exact: true });
      await expect(selectedPositionLine.locator('option:checked')).toHaveText(lineName);
      const positionsObserved = await inspectSurface(page, viewport, 'Админка / линия / контекст позиций', 'admin-lines-position-context');
      evidence.surfaces.push(positionsObserved.surface);
      evidence.findings.push(...positionsObserved.findings);

      await linesButton.click();
