      await expect(lineRow.getByRole('button', { name: 'Шаблоны состава', exact: true })).toBeVisible();
      await lineRow.getByRole('button', { name: 'Шаблоны состава', exact: true }).click();
      await expect(nav.getByRole('button', { name: 'Шаблоны состава', exact: true })).toHaveClass(/active/);
      const selectedTemplateLine = page.locator('#admin-template-line');
