      await expect(itemDetail).toBeVisible();
      await itemDetail.getByRole('button', { name: 'Закрыть окно', exact: true }).click();
      await expect(itemDetail).toBeHidden();
      evidence.interactions.push({ viewport, screen: 'Заказы / остаток', control: 'Израсходовать / Заказать / Пополнить / В архив / Back / Закрыть окно', result: 'PASS', detail: 'Каждое действие открыло правильную существующую форму; clean Browser Back закрыл только верхний слой; повторно открытая detail-карточка закрылась UI-кнопкой; записей не было.' });

