test('returns-create-submit-isolated: publish with photo survives reload without backend writes', async ({ page }, testInfo) => {
  test.skip(testInfo.project.name !== 'desktop-edge', 'Explicit viewport coverage runs once.');
  test.setTimeout(180_000);
  const evidence = { interactions: [] as InteractionEvidence[], surfaces: [] as SurfaceEvidence[], findings: [] as Finding[], gaps: [] as string[] };
  const png = Buffer.from('iVBORw0KGgoAAAANSUhEUgAAAAEAAAABCAQAAAC1HAwCAAAAC0lEQVR42mNk+A8AAQUBAScY42YAAAAASUVORK5CYII=', 'base64');

  for (const width of [1440, 360, 390, 430]) {
    const viewport = width === 1440 ? 'desktop' : String(width);
    await page.setViewportSize({ width, height: 844 });
    await loginAsAdmin(page);
    const attachment = {
      id: `ui-sweep-return-create-photo-${viewport}`,
      kind: 'PHOTO',
      originalName: `return-photo-${viewport}.png`,
      mimeType: 'image/png',
      sizeBytes: png.length,
      createdAt: new Date().toISOString(),
    };
    const created = {
      id: `ui-sweep-return-create-${viewport}`,
      description: 'Повреждение транспортной упаковки',
      photoUrl: 'attachment-pending',
      createdAt: new Date().toISOString(),
      article: 'АРТ-105',
      productName: 'Контрольный возврат с фото',
      mismatchReason: 'Повреждение транспортной упаковки',
      quantity: 3,
      unit: 'гофр',
      status: 'ACTIVE',
      attachments: [] as Array<typeof attachment>,
      author: { id: 'ui-sweep-author', displayName: 'Администратор', role: 'ADMIN', roleLabel: 'Администратор' },
      availableActions: ['partial-release'],
      quantitySummary: { original: '3', released: '0', remaining: '3', unit: 'гофр', canRelease: true },
      releaseHistory: [],
    };
    let published = false;
    const createBodies: Array<Record<string, unknown>> = [];
    const uploadBodies: string[] = [];
    const escapedWrites: string[] = [];
    const returnsRoute = async (route: import('@playwright/test').Route) => {
      const request = route.request();
      const url = new URL(request.url());
      if (request.method() === 'GET' && url.pathname === '/api/returns') {
        await route.fulfill({ status: 200, contentType: 'application/json', body: JSON.stringify(published ? [created] : []) });
        return;
      }
      if (request.method() === 'GET' && url.pathname === '/api/returns/publication-lines') {
        await route.fulfill({ status: 200, contentType: 'application/json', body: '[]' });
        return;
      }
      if (request.method() === 'POST' && url.pathname === '/api/returns') {
        createBodies.push(request.postDataJSON() as Record<string, unknown>);
        published = true;
        await route.fulfill({ status: 201, contentType: 'application/json', body: JSON.stringify(created) });
        return;
      }
      if (!['GET', 'HEAD', 'OPTIONS'].includes(request.method())) {
        escapedWrites.push(`${request.method()} ${url.pathname}`);
        await route.abort();
        return;
      }
      await route.continue();
    };
    const attachmentRoute = async (route: import('@playwright/test').Route) => {
      const request = route.request();
      const url = new URL(request.url());
      if (request.method() === 'POST' && url.pathname === '/api/attachments/upload') {
        uploadBodies.push(request.postDataBuffer()?.toString('utf8') ?? '');
        created.attachments = [attachment];
        await route.fulfill({ status: 201, contentType: 'application/json', body: JSON.stringify(attachment) });
        return;
      }
      if (request.method() === 'GET' && url.pathname === `/api/attachments/${attachment.id}/file`) {
        await route.fulfill({ status: 200, contentType: 'image/png', body: png });
        return;
      }
      if (!['GET', 'HEAD', 'OPTIONS'].includes(request.method())) {
        escapedWrites.push(`${request.method()} ${url.pathname}`);
        await route.abort();
        return;
      }
      await route.continue();
    };
    await page.route('**/api/returns**', returnsRoute);
    await page.route('**/api/attachments/**', attachmentRoute);

    try {
      await openMain(page, views.find((view) => view.id === 'Returns')!);
      const root = page.locator('.returns-screen');
      await root.getByRole('button', { name: 'Опубликовать возврат', exact: true }).click();
      const dialog = page.getByRole('dialog', { name: 'Возврат на производство', exact: true });
      await dialog.getByPlaceholder('Например, повреждённая упаковка').fill('  Контрольный возврат с фото  ');
      await dialog.getByLabel('Краткая причина', { exact: true }).fill('  Повреждение транспортной упаковки  ');
      await dialog.getByLabel('Артикул', { exact: true }).fill('  АРТ-105  ');
      await dialog.getByLabel('Количество', { exact: true }).fill('3');
      await dialog.getByRole('combobox', { name: 'Единица', exact: true }).selectOption('гофр');
      const chooserPromise = page.waitForEvent('filechooser');
      await dialog.getByRole('button', { name: 'Добавить фото', exact: true }).click();
      const chooser = await chooserPromise;
      await chooser.setFiles({ name: attachment.originalName, mimeType: 'image/png', buffer: png });
      await expect(dialog.getByText(attachment.originalName, { exact: true })).toBeVisible();
      await dialog.getByRole('button', { name: 'Опубликовать', exact: true }).click();

      await expect(dialog).toBeHidden();
      let card = root.locator('.returns-publication-card').filter({ hasText: created.productName });
      await expect(card).toBeVisible();
      await expect(root.getByRole('button', { name: /Новые 1/ })).toBeVisible();
      const observed = await inspectSurface(page, viewport, 'Возвраты / публикация / результат', 'returns-create-submit-result');
      evidence.surfaces.push(observed.surface);
      evidence.findings.push(...observed.findings);

      await page.reload({ waitUntil: 'domcontentloaded' });
      const reloadedRoot = page.locator('.returns-screen');
      card = reloadedRoot.locator('.returns-publication-card').filter({ hasText: created.productName });
      await expect(card).toBeVisible();
      await card.locator('.returns-publication-content > button').click();
      const detail = page.getByRole('dialog').filter({ has: page.locator('#return-detail-title') });
      await expect(detail).toBeVisible();
      await expect(detail.getByText(attachment.originalName, { exact: true })).toBeVisible();
      await page.goBack();
      await expect(detail).toBeHidden();
      await expect(card).toBeVisible();

      expect(createBodies).toHaveLength(1);
      expect(createBodies[0]).toEqual({
        title: 'Контрольный возврат с фото',
        reason: 'Повреждение транспортной упаковки',
        article: 'АРТ-105',
        quantity: 3,
        unit: 'гофр',
        lineId: null,
        photoUrl: 'attachment-pending',
        operationId: expect.stringMatching(/^[0-9a-f]{8}-[0-9a-f]{4}-4[0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$/i),
      });
      expect(uploadBodies).toHaveLength(1);
      expect(uploadBodies[0]).toContain('RETURN_RECORD');
      expect(uploadBodies[0]).toContain(created.id);
      expect(uploadBodies[0]).toContain('PHOTO');
      expect(uploadBodies[0]).toContain(attachment.originalName);
      expect(escapedWrites).toEqual([]);
      evidence.interactions.push({
        viewport,
        screen: 'Возвраты / публикация',
        control: 'Опубликовать / photo upload / list / reload / detail Back',
        result: 'PASS',
        detail: 'One intercepted create POST carried trimmed fields, numeric quantity and canonical operationId; one intercepted multipart upload carried RETURN_RECORD/entity/photo metadata. Browser memory rendered the card and attachment after reload and detail Back; no backend write occurred.',
      });
    } finally {
      await page.unroute('**/api/returns**', returnsRoute);
      await page.unroute('**/api/attachments/**', attachmentRoute);
      fs.writeFileSync(path.join(runtimeDir, 'runtime-returns-create-submit-isolated.json'), JSON.stringify(evidence, null, 2) + '\n');
    }
  }
});

