      parent = page.getByRole('dialog').filter({ has: page.locator('#return-detail-title') });
      await expect(parent).toBeVisible();
      await parent.getByRole('button', { name: 'Выдать часть', exact: true }).click();
      sheet = page.getByRole('dialog', { name: 'Выдать часть продукции' });
      await expect(sheet.getByLabel('Количество', { exact: true })).toHaveValue('');
      await sheet.getByLabel('Количество', { exact: true }).fill('1');
      const backComment = page.getByRole('textbox', { name: 'Комментарий *', exact: true }).filter({ visible: true });
