      const pollCloseModal = page.getByRole('dialog').filter({ has: page.getByRole('heading', { name: 'Новый опрос', exact: true }) });
      await expect(pollCloseModal).toBeVisible();
      await pollCloseModal.getByRole('button', { name: 'Закрыть', exact: true }).click();
      await expect(pollCloseModal).toBeHidden();

      await dialog.getByRole('button', { name: 'Прикрепить', exact: true }).click();
