        evidence.interactions.push({ viewport, screen: 'Чек-листы / библиотека', control: 'Preview / expand / pristine edit / focus-first Back / layer Back', result: 'PASS', detail: 'Template preview and pristine editor were opened locally; first Back blurred the auto-focused name field, second Back closed the builder; no save/archive/reorder request.' });

        await templateActions.getByRole('button', { name: 'Создать копию', exact: true }).click();
        const copyBuilder = page.getByRole('dialog').filter({ has: page.getByRole('heading', { name: 'Копия шаблона', exact: true }) });
        await expect(copyBuilder).toBeVisible();
        await capture('Чек-листы / локальная копия шаблона', 'checklists-template-copy-local');
        await copyBuilder.getByRole('button', { name: 'Отмена', exact: true }).click();
        await expect(copyBuilder).toBeHidden();

        await templateActions.getByRole('button', { name: 'Добавить пункт', exact: true }).click();
        const addExistingRow = page.getByRole('dialog').filter({ has: page.getByRole('heading', { name: 'Добавить пункт', exact: true }) });
        await expect(addExistingRow).toBeVisible();
        await capture('Чек-листы / добавить пункт существующего шаблона', 'checklists-template-add-row-local');
        await page.goBack();
        await expect(addExistingRow).toBeHidden();

        const existingRow = libraryCard.locator('.checklist-template-row-compact').first();
        if (await existingRow.count()) {
          await existingRow.getByRole('button', { name: 'Редактировать', exact: true }).click();
          const editExistingRow = page.getByRole('dialog').filter({ has: page.getByRole('heading', { name: 'Редактировать пункт', exact: true }) });
          await expect(editExistingRow).toBeVisible();
          await capture('Чек-листы / редактировать пункт существующего шаблона', 'checklists-template-edit-row-local');
          await page.goBack();
          await expect(editExistingRow).toBeHidden();

          await existingRow.getByRole('button', { name: 'Удалить', exact: true }).click();
          const archiveExistingRow = page.getByRole('dialog').filter({ has: page.getByRole('heading', { name: 'Удалить пункт из шаблона?', exact: true }) });
          await expect(archiveExistingRow).toBeVisible();
          await capture('Чек-листы / подтверждение удаления пункта', 'checklists-template-archive-row-confirm');
          await page.goBack();
          await expect(archiveExistingRow).toBeHidden();
        } else {
          evidence.gaps.push(`${viewport}: в первом library template нет строки для edit/archive modal proof.`);
        }

        await templateActions.getByRole('button', { name: 'В архив', exact: true }).click();
        const archiveTemplateConfirm = page.getByRole('dialog').filter({ has: page.getByRole('heading', { name: 'Архивировать шаблон', exact: true }) });
        await expect(archiveTemplateConfirm).toBeVisible();
        await capture('Чек-листы / подтверждение архивации шаблона', 'checklists-template-archive-confirm');
