      await expect(futurePanel).toBeVisible();
      evidence.interactions.push({ viewport, screen: 'Смена / следующая', control: 'Назначить не отметившегося / focus-first Back / layer Back', result: 'PASS', detail: 'The canonical future-context employee search shows short-query validation; Back first blurs the input and then closes only the search layer, restoring the planning panel without selecting anyone.' });
      await futurePanel.getByRole('button', { name: 'Плановые линии', exact: true }).click();
