      mimeType: 'text/plain',
      size: 1024,
      createdAt: now,
      author: 'Администратор',
      sourceType: 'TASK',
      sourceTitle: 'Проверка источника вложения',
      sourceId: taskId,
      sourceRoute: 'tasks',
