        (window as typeof window & { __archivePrintCount?: number }).__archivePrintCount = 0;
        window.print = () => { (window as typeof window & { __archivePrintCount?: number }).__archivePrintCount = ((window as typeof window & { __archivePrintCount?: number }).__archivePrintCount ?? 0) + 1; };
