      let modal = page.locator('.action-modal-backdrop');
      await expect(modal.getByRole('heading', { name: 'Закрыть проблему', exact: true })).toBeVisible();
      await modal.getByLabel('Что сделали').fill('Течь устранена, соединение проверено');
