      await expect.poll(() => issuePatches.length).toBe(2);
      await expect(detail.getByRole('tabpanel')).toContainText('Закрыта');
      const issuesObserved = await inspectSurface(page, viewport, 'Мойка / проблемы закрыты / результат', 'wash-active-issues-resolved-result');
      evidence.surfaces.push(issuesObserved.surface);
      evidence.findings.push(...issuesObserved.findings);

      await detail.getByRole('tab', { name: 'Контроль', exact: true }).click();
      const controlCard = detail.locator('.wash-feed-card').filter({ has: page.getByText('Проверить ограждение', { exact: true }) });
      await controlCard.getByRole('button', { name: 'Отметить выполненным', exact: true }).click();
      modal = page.locator('.action-modal-backdrop');
      await modal.getByLabel('Комментарий').fill('Ограждение установлено');
