      let modal = page.locator('.action-modal-backdrop').filter({ has: page.getByRole('heading', { name: 'Фото или комментарий', exact: true }) });
      await modal.getByLabel('Комментарий', { exact: true }).fill(messageText);
      await modal.locator('input[type="file"][accept*="text/plain"]').setInputFiles({ name: messageFileName, mimeType: 'text/plain', buffer: messageFile });
      await modal.getByRole('button', { name: 'Подтвердить', exact: true }).click();
      await expect.poll(() => messageBodies.length).toBe(1);
      await expect(modal).toBeVisible();
      await expect(modal.getByLabel('Комментарий', { exact: true })).toHaveValue(messageText);
      await expect(modal.getByText(messageFileName, { exact: true })).toBeVisible();
      await expect.soft(modal.getByText(messageError, { exact: true })).toBeVisible();
      const messageRejected = await inspectSurface(page, viewport, 'Мойка / фото или комментарий / ошибка сохранения', 'wash-message-submit-error');
      evidence.surfaces.push(messageRejected.surface);
      evidence.findings.push(...messageRejected.findings);

      await modal.getByRole('button', { name: 'Подтвердить', exact: true }).click();
