      const messageResult = await inspectSurface(page, viewport, 'Мойка / фото или комментарий / результат', 'wash-message-submit-result');
      evidence.surfaces.push(messageResult.surface);
      evidence.findings.push(...messageResult.findings);

      await page.reload({ waitUntil: 'domcontentloaded' });
      await openMain(page, views.find((view) => view.id === 'Wash')!);
      root = page.locator('.wash-screen');
