test('admin-department-deactivate-submit-outcome-isolated: rejection retention and inactive reload', async ({ page }, testInfo) => {
  test.skip(testInfo.project.name !== 'desktop-edge', 'Explicit viewport coverage runs once.');
  test.setTimeout(240_000);
  const evidence = { interactions: [] as InteractionEvidence[], surfaces: [] as SurfaceEvidence[], findings: [] as Finding[] };

  try {
    for (const width of [1440, 360, 390, 430]) {
      const viewport = width === 1440 ? 'desktop' : String(width);
      const id = `de462eac-bb51-4321-8441-27009e20${String(width).padStart(4, '0')}`;
      const name = `Служба упаковки ${width}`;
      const reason = `Изменение структуры ${viewport}`;
      const failure = 'Не удалось деактивировать отдел. Повторите попытку.';
      let isActive = true;
      const writes: Record<string, unknown>[] = [];
      const unexpected: string[] = [];
      const department = (factoryId: string | null) => ({ id, factoryId, name, code: `packing-${width}`, scope: 'LOCAL', isActive, userCount: 0 });

      await page.setViewportSize({ width, height: 844 });
      await loginAsAdmin(page);
      const adminRoute = async (route: import('@playwright/test').Route) => {
        const request = route.request();
        const url = new URL(request.url());
        if (request.method() === 'GET' && /^\/api\/admin\/factories\/[^/]+\/context$/.test(url.pathname)) {
          const response = await route.fetch();
          const context = await response.json();
          await route.fulfill({ response, contentType: 'application/json', body: JSON.stringify({ ...context, localDepartments: [department(url.pathname.split('/')[4])] }) });
          return;
        }
        if (request.method() === 'GET' && url.pathname === '/api/admin/departments') {
          await route.fulfill({ status: 200, contentType: 'application/json', body: JSON.stringify([department(url.searchParams.get('factoryId'))]) });
          return;
        }
        if (request.method() === 'PATCH' && url.pathname === `/api/admin/departments/${id}/status`) {
          const body = request.postDataJSON() as Record<string, unknown>;
          writes.push(body);
          if (writes.length === 1) {
            await route.fulfill({ status: 409, contentType: 'application/json', body: JSON.stringify({ message: failure }) });
            return;
          }
          isActive = body.isActive === true;
          await route.fulfill({ status: 200, contentType: 'application/json', body: '{}' });
          return;
        }
        if (!['GET', 'HEAD', 'OPTIONS'].includes(request.method())) {
          unexpected.push(`${request.method()} ${url.pathname}`);
          await route.abort();
          return;
        }
        await route.continue();
      };
      await page.route('**/api/admin/**', adminRoute);

      try {
        const openSection = async () => {
          if (!await page.getByRole('heading', { name: 'Администрирование', exact: true }).filter({ visible: true }).first().isVisible().catch(() => false)) {
            await openMain(page, views.find((view) => view.id === 'Admin')!);
          }
          await page.locator('.admin-task-nav').getByRole('button', { name: 'Отделы и службы', exact: true }).click();
        };
        const row = () => page.locator('article.admin-row').filter({ has: page.getByText(name, { exact: true }) });
        const dialog = () => page.getByRole('dialog').filter({ has: page.getByRole('heading', { name: `Деактивировать ${name}`, exact: true }) });

        await openSection();
        await expect(row()).not.toHaveClass(/dimmed/);
        await row().getByRole('button', { name: 'Деактивировать', exact: true }).click();
        await dialog().getByLabel('Причина', { exact: true }).fill(reason);
        await dialog().getByRole('button', { name: 'Подтвердить', exact: true }).click();
        await expect(dialog()).toBeVisible();
        await expect(dialog().getByText(failure, { exact: true })).toBeVisible();
        await expect(dialog().getByLabel('Причина', { exact: true })).toHaveValue(reason);
        const rejected = await inspectSurface(page, viewport, 'Админка / ошибка деактивации отдела', 'admin-department-deactivate-submit-error');
        evidence.surfaces.push(rejected.surface); evidence.findings.push(...rejected.findings);

        await dialog().getByRole('button', { name: 'Подтвердить', exact: true }).click();
        await expect(dialog()).toBeHidden();
        await expect(row()).toHaveClass(/dimmed/);
        await expect(row().getByRole('button', { name: 'Восстановить', exact: true })).toBeVisible();
        await row().scrollIntoViewIfNeeded();
        const disabled = await inspectSurface(page, viewport, 'Админка / отдел деактивирован', 'admin-department-deactivate-submit-result');
        evidence.surfaces.push(disabled.surface); evidence.findings.push(...disabled.findings);

        await page.reload();
        await openSection();
        await expect(row()).toHaveClass(/dimmed/);
        await expect(row().getByRole('button', { name: 'Восстановить', exact: true })).toBeVisible();
        await row().scrollIntoViewIfNeeded();
        const reloaded = await inspectSurface(page, viewport, 'Админка / отключённый отдел после reload', 'admin-department-deactivate-submit-reload');
        evidence.surfaces.push(reloaded.surface); evidence.findings.push(...reloaded.findings);

        expect(writes).toHaveLength(2);
        for (const body of writes) expect(body).toEqual({ isActive: false, reason, operationId: expect.stringMatching(/^[0-9a-f-]{36}$/i) });
        expect(writes[0].operationId).not.toBe(writes[1].operationId);
        expect(unexpected).toEqual([]);
        evidence.interactions.push({
          viewport,
          screen: 'Админка / отдел',
          control: 'Деактивировать / 409 / retained reason / retry / inactive reload',
          result: 'PASS',
          detail: 'Synthetic local department only: controlled Russian rejection retains the reason and active row; retry sends the exact inactive command, exposes Restore and survives browser-memory reload. Existing retained evidence separately proves focus/layer Back, Cancel and Restore. Backend persistence, department/factory authority, audit, concurrency and physical Android Back are not inferred.',
        });
      } finally {
        await page.unroute('**/api/admin/**', adminRoute);
      }
    }
  } finally {
    fs.writeFileSync(path.join(runtimeDir, 'runtime-admin-department-deactivate-submit-outcome-isolated.json'), JSON.stringify(evidence, null, 2) + '\n');
  }
});

