        await expect(row().getByText('Отключена', { exact: true })).toBeVisible();
        await expect(row().getByRole('button', { name: 'Восстановить', exact: true })).toBeVisible();
        await expect(row().getByLabel('Кому подчиняется')).toBeDisabled();
        await expect(row().getByLabel('Режим смены')).toBeDisabled();
        await row().scrollIntoViewIfNeeded();
        const disabled = await inspectSurface(page, viewport, 'Админка / должность отключена', 'admin-job-title-deactivate-submit-result');
        evidence.surfaces.push(disabled.surface); evidence.findings.push(...disabled.findings);

        await page.reload();
